   89:     uint16_t attribute;
   90: } emulator_roundtrip_event_t;
   91: 
   92: static StaticQueue_t s_roundtrip_queue_storage;
   93: static uint8_t s_roundtrip_queue_buffer[
   94:     EMULATOR_ROUNDTRIP_QUEUE_DEPTH * sizeof(emulator_roundtrip_event_t)
   95: ];
