   97: 
   98: static bool app_signal_handler(const ezb_app_signal_t *signal)
   99: {
  100:     const ezb_app_signal_type_t type = ezb_app_signal_get_type(signal);
  101:     const void *params = ezb_app_signal_get_params(signal);
  102:     if (type == EZB_ZDO_SIGNAL_SKIP_STARTUP) {
  103:         (void)ezb_bdb_start_top_level_commissioning(EZB_BDB_MODE_INITIALIZATION);
  104:     } else if (type == EZB_BDB_SIGNAL_STEERING) {
  105:         const ezb_bdb_signal_simple_params_t *steering = params;
  106:         ESP_LOGI(TAG, "network steering status=%u",
  107:                  steering == NULL ? 0xffU : (unsigned)steering->status);
  108:     } else if (type == EZB_BDB_SIGNAL_DEVICE_FIRST_START ||
  109:                type == EZB_BDB_SIGNAL_DEVICE_REBOOT) {
  110:         const bool factory_new = ezb_bdb_is_factory_new();
  111:         ESP_LOGI(TAG, "device %s factory_new=%u",
  112:                  type == EZB_BDB_SIGNAL_DEVICE_FIRST_START ? "first start" : "reboot",
  113:                  (unsigned)factory_new);
  114:         if (factory_new) {
  115:             (void)ezb_bdb_start_top_level_commissioning(EZB_BDB_MODE_NETWORK_STEERING);
  116:         }
  117:     }
  118:     return false;
  119: }
