  121: static void zcl_core_action_handler(
  122:     ezb_zcl_core_action_callback_id_t callback_id, void *message)
  123: {
  124:     if (callback_id != EZB_ZCL_CORE_SET_ATTR_VALUE_CB_ID ||
  125:         message == NULL || s_roundtrip_queue == NULL) {
  126:         return;
  127:     }
  128:     const ezb_zcl_set_attr_value_message_t *changed = message;
  129:     if (changed->info.cluster_role != EZB_ZCL_CLUSTER_SERVER) {
  130:         return;
  131:     }
  132: 
  133:     emulator_roundtrip_event_t event = {
  134:         .endpoint = changed->info.dst_ep,
  135:         .cluster = changed->info.cluster_id,
  136:         .attribute = 0U,
  137:     };
  138:     if (event.cluster == EMULATOR_CLUSTER_ON_OFF) {
  139:         event.attribute = EMULATOR_ATTR_ON_OFF;
  140:     } else if (event.cluster == EMULATOR_CLUSTER_LEVEL) {
  141:         event.attribute = EMULATOR_ATTR_CURRENT_LEVEL;
  142:     } else {
  143:         return;
  144:     }
  145: 
  146:     if (xQueueSend(s_roundtrip_queue, &event, 0) != pdPASS) {
  147:         ESP_LOGW(TAG, "roundtrip report queue full ep=%u cluster=0x%04x",
  148:                  event.endpoint, event.cluster);
  149:     } else {
  150:         ESP_LOGI(TAG, "writable state changed ep=%u cluster=0x%04x; report queued",
  151:                  event.endpoint, event.cluster);
  152:     }
  153: }
